AS r("lessonId" text,"lessonTitle" text,"sourcePage" integer,activity_order integer,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE eligible integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_grade3_8_story_32)<>32
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_grade3_8_story_32)<>8
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.bh_grade3_8_story_32)<>32
 OR EXISTS(SELECT 1 FROM pg_temp.bh_grade3_8_story_32 t WHERE
 t.activity_order NOT BETWEEN 204 AND 207 OR t.activity_type<>'multiple_choice'
 OR length(t.content->>'originalText')<170 OR length(t.prompt)<15
 OR t.content ? 'correct' OR t.content ? 'answer'
 OR jsonb_array_length(t.content->'options')<>3
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(t.content->'options') a WHERE a=t.answer->>'correct'))
 THEN RAISE EXCEPTION 'Malformed 8 original story activities or an answer leak'; END IF;
 SELECT count(DISTINCT l.id) INTO eligible
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_grade3_8_story_32 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND co.code='BH' AND g.grade_number=3
 AND l.source_pdf_url IS NOT NULL AND l.content LIKE '%نص تعليمي أصلي داعم:%'
 AND position(t.content->>'originalText' IN l.content)>0
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=2
 AND (SELECT max(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=203
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts t JOIN public.lesson_activities a ON a.id=t.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts t JOIN public.questions q ON q.id=t.question_id WHERE q.lesson_id=l.id);
 IF eligible<>8 THEN RAISE EXCEPTION 'Read-only source text/lesson scope/student history drift: got % / 8',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G3_EIGHT_DISTINCT_READING_32_ORIGINAL_20261030')
 THEN RAISE EXCEPTION 'Batch already inserted, no duplicates'; END IF;
 INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ نص ضاديوم الإثرائي الأصلي ثم اختر الإجابة المناسبة. لم تثبت مطابقة الكتاب الوزاري.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_grade3_8_story_32 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND co.code='BH' AND g.grade_number=3
 AND position(t.content->>'originalText' IN l.content)>0
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>32 THEN RAISE EXCEPTION 'Atomic rollback: % Grade3 activities, expected 32',inserted; END IF;
END $safe$;
COMMIT;